+/// Expanded constructor branches; this exercises circuit satisfaction and
+/// compatibility with the same compiled relation, not Pari proof verification.
+#[test]
+fn expanded_transfer_branches_share_relation_and_reject_branch_mutations() {
+    let p = Parameters::load().unwrap();
+    let g = Generators::derive(&p);
+    let facts = fixtures::load().unwrap();
+    let first = fixtures::build(&p, &g, &facts[0]).unwrap();
+    eprintln!("phase: compile expected relation");
+    let (circuit, indices) = build(|ctx| constrain(ctx, &p, &g, &first, &digest(&p, &g, &first)));
+    let layout = pari::InputLayout::new(vec![indices[0]], vec![vec![indices[1]]]).unwrap();
+    let relation = pari::Relation::compile(&circuit, &layout).unwrap();
+    drop(circuit);
+    eprintln!("phase: expected relation ready; source circuit released");
+    let mut cases = Vec::new();
+    let mut real_second = facts[0].clone();
+    real_second.scenario = "real_second".into();
+    real_second.optional_dummy = false;
+    real_second.inputs = ["60".into(), "40".into()];
+    real_second.spend_positions[1] = 1;
+    cases.push(fixtures::build(&p, &g, &real_second).unwrap());
+    let mut continuation = facts[5].clone();
+    continuation.scenario = "nonzero_continuation".into();
+    continuation.volume.prior = "10".into();
+    continuation.volume.successor = "35".into();
+    continuation.registry.daily_limit = "35".into();
+    cases.push(fixtures::build(&p, &g, &continuation).unwrap());
+    let mut self_transfer = facts[0].clone();
+    self_transfer.scenario = "ordinary_self_padding".into();
+    self_transfer.same_affine_address = true;
+    self_transfer.receiver_position = self_transfer.sender_position;
+    self_transfer.volume.use_real = false;
+    self_transfer.volume.successor = "0".into();
+    cases.push(fixtures::build(&p, &g, &self_transfer).unwrap());
+    let mut fee = self_transfer.clone();
+    fee.scenario = "fee_self".into();
+    fee.volume.context = "2".into();
+    fee.volume.day_start = "0".into();
+    let mut fee_witness = fixtures::build(&p, &g, &fee).unwrap();
+    // The general fixture builder emits ordinary padding hashes. Fee semantics
+    // instead publishes zero accumulator outputs; this is the native branch.
+    fee_witness.volume.nullifier = Scalar::zero();
+    fee_witness.volume.commitment = Scalar::zero();
+    cases.push(fee_witness);
+    let mut no_change = facts[1].clone();
+    no_change.scenario = "unregulated_no_change_filler".into();
+    no_change.outputs = ["100".into(), "0".into()];
+    cases.push(fixtures::build(&p, &g, &no_change).unwrap());
+    let mut zero_required = facts[2].clone();
+    zero_required.scenario = "zero_required_spend".into();
+    zero_required.inputs = ["0".into(), "0".into()];
+    zero_required.outputs = ["25".into(), "0".into()];
+    cases.push(fixtures::build(&p, &g, &zero_required).unwrap());
+    for (i, witness) in cases.iter().enumerate() {
+        eprintln!("phase: expanded branch {i} valued circuit");
+        let (valued, _) = build_with_values(|ctx|
+            constrain(ctx, &p, &g, witness, &digest(&p, &g, witness)));
+        assert!(valued.is_satisfied(), "expanded branch {i}");
+        eprintln!("phase: expanded branch {i} full relation witness comparison");
+        relation.witness(&valued, &layout,
+            vec![pari::Opening::random(&mut rand10::rng())]).unwrap();
+    }
+    drop(relation);
+    drop(layout);
+    eprintln!("phase: expected relation released; semantic negative controls");
+    let mut dummy_facts = real_second.clone();
+    dummy_facts.optional_dummy = true;
+    dummy_facts.spend_positions[1] = 0;
+    let wrong_dummy = fixtures::build(&p, &g, &dummy_facts).unwrap();
+    assert!(!satisfied(&p, &g, &wrong_dummy), "nonzero second spend cannot be padding");
+    let mut over_limit = cases[1].clone();
+    over_limit.registry.leaf.daily_limit = Scalar::from(34);
+    over_limit.asset_anchor = tree::native_root(&p, Tree::Asset,
+        over_limit.registry.leaf.commitment(&p), facts[5].registry.position,
+        &over_limit.registry.path.siblings);
+    assert!(!satisfied(&p, &g, &over_limit), "continuation exceeds undisclosed daily limit");
+    let mut real_self_facts = self_transfer.clone();
+    real_self_facts.volume.use_real = true;
+    real_self_facts.volume.successor = "25".into();
+    let real_self = fixtures::build(&p, &g, &real_self_facts).unwrap();
+    assert!(!satisfied(&p, &g, &real_self), "self-transfer cannot use real accumulator");
+    let mut nonzero_fee_volume = cases[3].clone();
+    nonzero_fee_volume.volume.nullifier = Scalar::one();
+    assert!(!satisfied(&p, &g, &nonzero_fee_volume), "fee accumulator outputs must be zero");
+    let mut wrong_filler = cases[4].clone();
+    wrong_filler.routing.tags[0] += &Scalar::one();
+    assert!(!satisfied(&p, &g, &wrong_filler), "no-change routing tag is nonce-bound");
+    let mut zero_recipient_facts = zero_required.clone();
+    zero_recipient_facts.outputs[0] = "0".into();
+    let zero_recipient = fixtures::build(&p, &g, &zero_recipient_facts).unwrap();
+    assert!(!satisfied(&p, &g, &zero_recipient), "recipient output is required positive");
+}
